class Solution {
  public long maximumTotalDamage(int[] power) {
    int[] sorted = power.clone();
    Arrays.sort(sorted);
    int n = sorted.length, m = 0;
    int[] values = new int[n];
    long[] counts = new long[n];
    for (int x : sorted) {
      if (m > 0 && values[m - 1] == x) counts[m - 1]++;
      else {
        values[m] = x;
        counts[m++] = 1;
      }
    }
    long[] dp = new long[m]; // best total using the first i + 1 distinct values
    int compatible = -1; // last value at least 3 below values[i]
    for (int i = 0; i < m; i++) {
      while (compatible + 1 < i && values[compatible + 1] <= values[i] - 3) compatible++;
      long take = values[i] * counts[i] + (compatible >= 0 ? dp[compatible] : 0);
      dp[i] = Math.max(i > 0 ? dp[i - 1] : 0, take);
    }
    return dp[m - 1];
  }
}
